// The dedicated worker the SDK starts for the core (RFC 0009, "Open and
// close"; Carsten, 2026-11-12, NOC-274). It loads the core's WebAssembly
// module, shipped next to it in the package's build output, and answers
// each message, one bridge request in CBOR, with the bridge's answer, in
// order, as `{answer}`. The core's fold events, which the SDK's
// subscriptions re-run on, go to the page as `{event}`. The module's glue is
// generated by wasm-bindgen at build time (packages/sdk/build.mjs); it is
// not in src/.
//
// The worker holds the Web Lock `nocentraldb/<name>/worker` from its open
// on, while it may hold the database's OPFS handles, and the next worker
// waits for it before it opens (NOC-352). Asked to stop, the worker answers
// what it took, closes the database, gives the handles back, releases the
// lock and ends itself. Ending it from the page would leave the handles to
// the browser, which may free them later than the lock passes on, and the
// next worker's open would fail. In WebKit the worker can give them back
// only while its page runs, so a tab that freezes right after it gave the
// database up keeps them until it runs again; the next worker waits until
// then (docs/getting-started-browser.md, "Safari"), and while it waits its
// tab reports `waitingForTab` in `db.durability` (NOC-355).

import { decode, encode } from "./cbor.ts";
import { guardCore } from "./coreGuard.ts";
import { waitNotice } from "./waitNotice.ts";
// @ts-expect-error: generated into dist/wasm/ by the build step.
import init, { Core } from "./wasm/nocentraldb_wasm.js";

type Bridge = {
  handle(request: Uint8Array): Promise<Uint8Array>;
  listen(listener: (event: Uint8Array) => void): void;
  release(): boolean;
};

const post = (message: { answer?: Uint8Array; event?: Uint8Array }) => {
  const bytes = message.answer ?? message.event;
  (self as unknown as Worker).postMessage(message, bytes ? [bytes.buffer] : []);
};

const ready: Promise<Bridge> = init({
  module_or_path: new URL("./wasm/nocentraldb_wasm_bg.wasm", import.meta.url),
}).then(() => {
  const core = new Core() as Bridge;
  core.listen((event) => post({ event }));
  return core;
});

// Requests are answered one at a time, in the order they came.
let queue: Promise<unknown> = Promise.resolve();

const core = guardCore(
  ready.then((bridge) => (request) => bridge.handle(request)),
);
const answer = core.answer;

// An error nothing caught in this worker comes from the core: a trap in a
// step it runs after a call returned, as when a write is too large for its
// memory (NOC-426). The guard answers the waiting request and every later
// one with `storageFailed`; the error stops here, so the page sees the
// nc.Error and no uncaught one.
self.addEventListener("error", (event) => {
  event.preventDefault();
  core.failed(event.error ?? event.message);
});
self.addEventListener("unhandledrejection", (event) => {
  event.preventDefault();
  core.failed(event.reason);
});

/** What the page sends, besides bridge requests, to end the worker (workerHost.ts). */
const STOP = "stop";

// The lock this worker holds while it may hold the database's storage:
// `held` once it has it, `freed` once it gave it back.
let held: (() => void) | undefined;
let freed: Promise<unknown> = Promise.resolve();

/** Tells this worker's tab whether it waits for the storage another tab still holds (NOC-355): the tab reports it as `db.durability`'s `waitingForTab`. */
const waiting = waitNotice((waiting) =>
  post({ event: encode({ event: "waitingForTab", waiting }) }),
);

/** Asks for the lock of the database `name`; `holding` runs once it is held, `busy` at once if another worker holds it. */
const request = (name: string, ifAvailable: boolean, holding: () => void) =>
  navigator.locks.request(
    `nocentraldb/${name}/worker`,
    { ifAvailable },
    (lock) =>
      lock === null
        ? false
        : new Promise<void>((done) => {
            held = done;
            holding();
          }),
  );

/** Holds the lock of the database `name`; while a worker that is still ending holds it, waits, and says so (NOC-355). */
const hold = (name: string) =>
  new Promise<void>((taken) => {
    const tried = request(name, true, taken);
    freed = tried;
    void tried.then((answer) => {
      if (answer !== false) return;
      waiting.started();
      freed = request(name, false, () => {
        waiting.ended();
        taken();
      });
    });
  });

/** The database an `open` request names, or undefined for any other request. */
const opens = (request: Uint8Array): string | undefined => {
  try {
    const { call, args } = decode(request) as {
      call?: string;
      args?: { name?: unknown };
    };
    return call === "open" && typeof args?.name === "string"
      ? args.name
      : undefined;
  } catch {
    return undefined;
  }
};

/**
 * How often an open that found the storage held is tried again, and how
 * long it waits between tries, in milliseconds. A worker that ended
 * before it gave the storage back, because its tab closed, leaves the
 * handles to the browser, which may free them after the lock (NOC-352).
 */
const RETRIES = 30;
const RETRY_AFTER = 100;

/** Whether `answer` says the storage could not be opened. */
const storageFailed = (answer: Uint8Array) =>
  (decode(answer) as { error?: { code?: string } }).error?.code ===
  "storageFailed";

/** The answer to an open of the database `name`: once its lock is held, and tried again while another worker's handles are not yet free. */
const open = async (name: string, request: Uint8Array) => {
  if (held === undefined && "locks" in navigator) await hold(name);
  let answered = await answer(request.slice());
  for (let tried = 0; tried < RETRIES && storageFailed(answered); tried++) {
    await new Promise((resolve) => setTimeout(resolve, RETRY_AFTER));
    answered = await answer(request.slice());
  }
  return answered;
};

/** Closes the database, gives its handles and the lock back, and ends the worker. */
const stop = async () => {
  try {
    (await ready).release();
  } catch {
    // The module did not load: there are no handles to give back.
  }
  held?.();
  await freed;
  self.close();
};

self.onmessage = (event: MessageEvent<Uint8Array | typeof STOP>) => {
  const request = event.data;
  if (request === STOP) {
    queue = queue.then(stop);
    return;
  }
  queue = queue.then(async () => {
    const name = opens(request);
    post({
      answer:
        name === undefined ? await answer(request) : await open(name, request),
    });
  });
};
